# Anatomy quiz content. Each question: dict(q, a (correct), w (3 wrong), why, art=(name,[hl]) optional)
# First option listed is correct; the builder shuffles deterministically.

def Q(q, a, w, why, art=None):
    return dict(q=q, a=a, w=w, why=why, art=art)

